CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone varchar(20) NOT NULL UNIQUE, full_name text NOT NULL DEFAULT '', role text NOT NULL DEFAULT 'RIDER' CHECK(role IN ('RIDER','MECHANIC','ADMIN')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS otp_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone varchar(20) NOT NULL, otp_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS otp_phone_idx ON otp_challenges(phone,created_at DESC);
CREATE TABLE IF NOT EXISTS vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), brand text NOT NULL, model text NOT NULL, registration text, year int, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mechanics (user_id uuid PRIMARY KEY REFERENCES users(id), skills text[] NOT NULL DEFAULT '{}', brands text[] NOT NULL DEFAULT '{}', verification text NOT NULL DEFAULT 'PENDING' CHECK(verification IN ('PENDING','VERIFIED','REJECTED','SUSPENDED')), online boolean NOT NULL DEFAULT false, location geography(Point,4326), radius_km int NOT NULL DEFAULT 10, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS mechanic_geo_idx ON mechanics USING gist(location);
CREATE TABLE IF NOT EXISTS rescues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL REFERENCES users(id), vehicle_id uuid NOT NULL REFERENCES vehicles(id), issue text NOT NULL, description text NOT NULL DEFAULT '', location geography(Point,4326) NOT NULL, status text NOT NULL DEFAULT 'SEARCHING' CHECK(status IN ('SEARCHING','OFFERS_RECEIVED','MECHANIC_SELECTED','EN_ROUTE','ARRIVED','INSPECTION','ESTIMATE_PENDING','ESTIMATE_APPROVED','REPAIRING','COMPLETED','CANCELLED')), mechanic_id uuid REFERENCES users(id), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rider_id,idempotency_key));
CREATE INDEX IF NOT EXISTS rescue_rider_idx ON rescues(rider_id,created_at DESC);
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rescue_id uuid NOT NULL REFERENCES rescues(id), mechanic_id uuid NOT NULL REFERENCES users(id), eta_minutes int NOT NULL CHECK(eta_minutes BETWEEN 1 AND 240), visit_paise int NOT NULL CHECK(visit_paise >= 0), note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rescue_id,mechanic_id));
CREATE TABLE IF NOT EXISTS status_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rescue_id uuid NOT NULL REFERENCES rescues(id), actor_id uuid NOT NULL REFERENCES users(id), from_status text, to_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS estimates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rescue_id uuid NOT NULL REFERENCES rescues(id), version int NOT NULL, items jsonb NOT NULL, total_paise int NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','DECLINED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rescue_id,version));
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rescue_id uuid NOT NULL REFERENCES rescues(id), estimate_id uuid NOT NULL REFERENCES estimates(id), gateway_reference text UNIQUE, amount_paise int NOT NULL, status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SUCCESS','FAILED','REFUNDED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events (gateway_event_id text PRIMARY KEY, payment_id uuid NOT NULL REFERENCES payments(id), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rescue_id uuid NOT NULL UNIQUE REFERENCES rescues(id), rider_id uuid NOT NULL REFERENCES users(id), mechanic_id uuid NOT NULL REFERENCES users(id), rating int NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, subject_id uuid, created_at timestamptz NOT NULL DEFAULT now());
